INSERT INTO tour_poi (content_id, content_type_id, source, title, addr, map_x, map_y,
    first_image, area_code, artist, recommend_reason, review_status, raw_json) VALUES
('kride-media-8032', 'HOLY', 'CRAWL', '도이창커피농장', '경기도 수원시 팔달구 화서문로32번길 21', 127.01215, 37.284245, NULL, '31', '학교 2017', '15회에서 홍남주(설인아)는 학교를 그만두고 이곳에서 아르바이트를 한다. 송대휘(장동윤)가 찾아와 커피를 주문한다. 그는 그녀가 교대 근무를 마칠 때까지 그녀를 기다리며 그녀가 보고 싶으니까 학교로 돌아오라고 말한다.', 'APPROVED', '{"dataset": "kcisa_media_2023", "tmp_poi_id": "8032", "category": "kculture", "sub_category": "cafe", "sido": "경기도", "sigungu": "수원시"}'::jsonb),
('kride-media-8033', 'HOLY', 'CRAWL', '블루힙', '경기도 수원시 팔달구 권광로 173 남경빌딩 2층', 127.031933, 37.2630833, NULL, '31', '한 번 다녀왔습니다', '전날 밤 자신의 집에서 어머니와 형 윤규진(이상엽) 앞에서 만취한 것에 대해 사과하는 곳으로 나온다.', 'APPROVED', '{"dataset": "kcisa_media_2023", "tmp_poi_id": "8033", "category": "kculture", "sub_category": "cafe", "sido": "경기도", "sigungu": "수원시"}'::jsonb),
('kride-media-8034', 'HOLY', 'CRAWL', '콤마앤콤마', '경기도 파주시 하우안길 20', 126.76606, 37.717548, NULL, '31', '한 사람만', '11화에서 경찰관 오진규(장인섭)가 성미도(레드벨벳 조이)의 차를 이 곳으로 추적한다. 이혼 전문 변호사 지윤서(이영진)와의 만남에서 강세연(강예원)을 만난다.', 'APPROVED', '{"dataset": "kcisa_media_2023", "tmp_poi_id": "8034", "category": "kculture", "sub_category": "cafe", "sido": "경기도", "sigungu": "파주시"}'::jsonb),
('kride-media-8035', 'HOLY', 'CRAWL', '동서울종합터미널', '서울특별시 광진구 강변역로 50', 127.09418, 37.534537, NULL, '1', '한 사람만', '바닷가 은신처를 떠난 표인숙(안은진)과 민우천(김경남)은 버스를 타고 서울로 돌아오며 이 버스터미널에 도착한다. 터미널을 나오자 인숙은 몸이 안 좋아지기 시작했고, 우천에게 이제 그만 도망쳐야 할 때라고 말한다.', 'APPROVED', '{"dataset": "kcisa_media_2023", "tmp_poi_id": "8035", "category": "kculture", "sub_category": "playground", "sido": "서울특별시", "sigungu": "광진구"}'::jsonb),
('kride-media-8036', 'HOLY', 'CRAWL', '고척공구상가', '서울특별시 구로구 중앙로3길 50', 126.86057, 37.499967, NULL, '1', '한 사람만', '민우천(김경남)이 향하는 1화에서 보듯 ''나래청소''는 사설탐정회사의 표지인 ''나래청소''가 있는 건물이다.', 'APPROVED', '{"dataset": "kcisa_media_2023", "tmp_poi_id": "8036", "category": "kculture", "sub_category": "playground", "sido": "서울특별시", "sigungu": "구로구"}'::jsonb),
('kride-media-8037', 'HOLY', 'CRAWL', '양재역(서초구청)', '서울특별시 서초구 남부순환로 2585', 127.03412, 37.484457, NULL, '1', '한 사람만', '11회에서 표인숙(안은진)과 민우천(김경남)은 이 역(''고산역''으로 나타남)의 10번 출구로 나오며, 그들과 교류를 원하는 다양한 사람들에게 즉시 다가가는데, 그런 다음 그들은 12번 출구를 통과하여 차에 치인 소년을 간신히 구한다.', 'APPROVED', '{"dataset": "kcisa_media_2023", "tmp_poi_id": "8037", "category": "kculture", "sub_category": "station", "sido": "서울특별시", "sigungu": "서초구"}'::jsonb),
('kride-media-8038', 'HOLY', 'CRAWL', '녹사평대로40길', '서울특별시 용산구 녹사평대로40길 55-3', 126.98883, 37.534558, NULL, '1', '한 사람만', '한사람만(한사람만) 10회에서 민우천(김경남)은 병원에서 탈출한 후 표인숙(안은진)을 이 골목길로 데려간다.', 'APPROVED', '{"dataset": "kcisa_media_2023", "tmp_poi_id": "8038", "category": "kculture", "sub_category": "playground", "sido": "서울특별시", "sigungu": "용산구"}'::jsonb),
